  'demo.bar.tag': '演示',
  'demo.bar.opening': '正在打开 Curahold 演示',
  'demo.bar.step.db': '正在此标签页中启动 Postgres。任何数据都不会离开你的浏览器。',
  'demo.bar.step.schema': '正在创建数据表和访问规则。',
  'demo.bar.step.data': '正在载入一组虚构的客户。',
