  'demo.bar.failed': '演示无法启动。请刷新页面重试。',
  'demo.bar.stuck': '演示无法为你登录。',
  'demo.bar.note': '虚构数据，完全在此标签页中运行。刷新即重新开始。',
  'demo.bar.as': '当前身份',
  'demo.bar.language': '演示语言',
  'demo.bar.tries': '试试这些',
  'demo.bar.tours': '全部导览',
  'demo.bar.reset': '重新开始',
  'demo.bar.customer': '客户 · {company} 门户',
  'demo.idea.1': '按 N，输入“和 Acme 的续约通话 friday @陈思雨 #维途 !high”：日期、负责人、客户和优先级会自动填好。粘贴多行，每一行都会成为一个任务。',
  'demo.idea.2': '在“我的任务”中点击任务前的圆圈，即可完成；在底部的通知里可以撤销。',
  'demo.idea.3': '客户 → 所有客户：“卡片”视图显示谁需要关注以及原因。也看看“续约”和“产品”视图。',
  'demo.idea.4': '客户 → 商机：把一个商机拖到其他阶段，或放到“已赢单”上，顶部的预测会立即更新。',
  'demo.idea.5': '洞察 → 报表：用“新建报表”搭建自己的报表，或打开现成的报表修改。洞察 → 仪表板：“添加”会把现成的仪表板放到你的主页上。',
  'demo.idea.6': '洞察 → 团队：谁在负责什么、什么已逾期，以及与每个人一对一面谈的视图。工作 → 时间线显示接下来几周。',
  'demo.idea.7': '客户 → 业务回顾：谁的回顾已逾期或即将到来。点“完成”记录一次回顾，下次日期随之顺延。节奏在 设置 → 目标与节奏 中设定。',
  'demo.idea.8': '在“客户成功 — 综合”看板上打开一个任务：关注、关联一个任务（“等待”）、花费时间、清单，以及底部的历史。也试试看板上的筛选和视图。',
  'demo.idea.9': '在客户页面上，“应用行动手册”一键添加入门任务。',
  'demo.idea.10': '删除一个任务或客户，然后在底部通知中选择“撤销”，或从你的菜单打开回收站。删除的内容会保留 30 天，并连同其下的一切一起恢复。',
  'demo.idea.11': '左下角的 CuraAI：用你自己的话提问（例如“如何导入客户？”）。答案来自文档，并附上出处。',
  'demo.idea.12': '设置 → CRM 和电子表格：连接一个 CRM。一个带有虚构数据的模拟 CRM 会走完真实的步骤：授权、选择导入内容、匹配字段、开始首次同步。',
  'demo.idea.13': '打开一个客户（例如维途出行）：在时间线上记录一次通话，再看看健康评分旁的“为什么？”。',
  'demo.idea.14': '设置 → 健康评分：调整权重，预览会立即显示每个客户的分数。',
  'demo.idea.15': 'Ctrl K（Mac 上为 ⌘ K）可以找到任何客户、任务、人员或设置。',
  'demo.idea.16': '在看板上选中多个任务，一起修改，然后撤销。',
  'demo.idea.17': '设置 → 角色和权限：“以……的视角查看”让你从某位成员的角度看界面。',
  'demo.idea.18': '在上方切换到陈思雨或周婷，看看同样的界面有什么变化。',
  'demo.idea.19': '在上方切换到吴佳琪（客户）：在奎菲尔德的门户中，她只能看到与她共享的内容。提交一个请求并回复；然后以陈思雨的身份在“客户成功 — 综合”看板上打开它，选择“回复客户”。',
  'demo.idea.20': '左下角你的菜单：外观（深色模式）、语言和键盘快捷键（或按 ?）。',
  'demo.tour.area.start': '从这里开始',
  'demo.tour.area.start.blurb': '几分钟了解产品：团队每天早上第一眼看到什么，以及一切都在哪里。',
  'demo.tour.area.customers': '客户与健康度',
  'demo.tour.area.customers.blurb': '每个客户一个页面，健康评分不只给出颜色，还说明原因。',
