  'demo.tour.area.ai': 'CuraAI',
  'demo.tour.area.ai.blurb': '用你自己的话提问，答案来自你的工作区和文档，并附出处。',
  'demo.tour.area.portal': '客户门户',
  'demo.tour.area.portal.blurb': '为每个客户开一个专属门户：共享的工作、请求和回复都在一处。',
  'demo.tour.area.connect': '连接与设置',
  'demo.tour.area.connect.blurb': '带上你的 CRM，让 Curahold 贴合你的流程，并决定谁能看到什么。',
  'demo.tour.goal.keep': '留住客户',
  'demo.tour.goal.grow': '续约与增购',
  'demo.tour.goal.week': '安排团队的一周',
  'demo.tour.goal.answer': '更快回应客户',
