  'demo.tour.goal.setup': '按你的方式设置',
  'demo.tour.role.csm': '客户成功',
  'demo.tour.role.sales': '销售',
  'demo.tour.role.lead': '团队负责人',
  'demo.tour.role.exec': '管理层',
  'demo.tour.role.ops': '运营与管理',
  'demo.tour.overview.title': '两分钟了解 Curahold',
  'demo.tour.overview.blurb': '主页、你的客户、团队负荷和 CuraAI——最适合入门的导览。',
  'demo.tour.overview.1.title': '这就是真实的产品',
  'demo.tour.overview.1.body': '这不是录屏：Curahold 正在这个标签页中运行，用的是一家虚构公司和它的客户。你是林悦，负责那里的客户成功。随时可以四处点点，导览会等你。',
  'demo.tour.overview.2.title': '每个角色都有自己的主页',
  'demo.tour.overview.2.body': '团队成员看“我的一天”，负责人看“团队视图”，管理层看“领导层摘要”。每个页面都由卡片组成，可以通过“编辑页面”移动、添加和移除。',
  'demo.tour.overview.3.title': '谁在负责什么',
  'demo.tour.overview.3.body': '每个人的客户、未完成的工作和逾期任务一目了然，负责人不等别人开口就能看出谁已经超负荷。点击名字可以查看此人的一周。',
  'demo.tour.overview.4.title': '需要你的客户排在最前',
  'demo.tour.overview.4.body': '每个客户都是一张卡片，按需要关注的程度排序，卡片还会说明原因：评分偏低、工作逾期、续约临近。',
  'demo.tour.overview.5.title': '随处提问，问什么都行',
  'demo.tour.overview.5.body': 'CuraAI 回答关于你的工作区和产品的问题，每个答案都附有出处。它在每个界面上都在。',
  'demo.tour.health.title': '弄清客户为什么有风险',
  'demo.tour.health.blurb': '会自我说明的健康评分，以及汇集在一条时间线上的客户全部经过。',
  'demo.tour.health.1.title': '从最上面那个开始',
  'demo.tour.health.1.body': '列表把需要关注的客户排在最前。最上面的卡片就是眼下最紧急的那个。',
  'demo.tour.health.2.title': '打开它',
  'demo.tour.health.2.body': '点击客户名称。',
  'demo.tour.health.3.title': '不只是一个颜色',
  'demo.tour.health.3.body': '健康评分附带原因。点击“为什么？”。',
  'demo.tour.health.4.title': '每一分都有来由',
  'demo.tour.health.4.body': '上次沟通的时间、逾期工作、支持请求、使用情况——每一项得了多少分、走势如何都看得到。由你选择评分项及其权重。',
  'demo.tour.health.5.title': '全部经过，集中一处',
  'demo.tour.health.5.body': '通话、会议、备注、邮件和变更都在一条时间线上——从这里打开。在那里记录一次通话，评分就会把它算进去。',
  'demo.tour.health-setup.title': '打造属于你的健康评分',
  'demo.tour.health-setup.blurb': '决定计入什么、占多少比重，并在保存前看到每个客户的新分数。',
  'demo.tour.health-setup.1.title': '评分由什么构成',
  'demo.tour.health-setup.1.body': '每一项都是一个信号——距上次沟通的天数、逾期工作、支持请求、你自己的字段——各有权重。改一个权重，看看会发生什么。',
  'demo.tour.health-setup.2.title': '保存之前先看效果',
  'demo.tour.health-setup.2.body': '“健康”和“有风险”分别从哪里开始，以及每个客户将得到的分数预览。第二天早上不会有意外。',
  'demo.tour.renewals.title': '续约再也不会措手不及',
