  'demo.tour.renewals.4.body': '续约与会议、通话和回顾一起显示在日历上。可以在这里开关任意类型。',
  'demo.tour.pipeline.title': '推进商机，看预测变化',
  'demo.tour.pipeline.blurb': '对照本季度目标、按阶段排列的商机，以及第一天就能用的仪表板。',
  'demo.tour.pipeline.1.title': '本季度一目了然',
  'demo.tour.pipeline.1.body': '本季度的目标和团队的完成进度，随商机推进而变化。',
  'demo.tour.pipeline.2.title': '按阶段排列的商机',
  'demo.tour.pipeline.2.body': '把一个商机拖到其他阶段或“已赢单”，上方的目标线会立即变化。试试看。',
  'demo.tour.pipeline.3.title': '卡片上一应俱全',
  'demo.tour.pipeline.3.body': '金额、客户、预计成交日期和负责人——客户的健康度也在旁边，因为商机是否稳妥，取决于背后的客户。',
  'demo.tour.pipeline.4.title': '现成的仪表板',
  'demo.tour.pipeline.4.body': '销售管道、续约与风险、团队绩效、管理层摘要。可以直接使用，也可以修改。',
  'demo.tour.quick-add.title': '像说一句话一样写任务',
  'demo.tour.quick-add.blurb': '在任何地方按 N；日期、负责人、客户和优先级会自动填好。',
  'demo.tour.quick-add.1.title': '按截止时间排好的工作',
  'demo.tour.quick-add.1.body': '“我的任务”汇集了所有看板上属于你的工作，分为已逾期、今天、本周和之后。',
  'demo.tour.quick-add.2.title': '按 N，然后直接写',
  'demo.tour.quick-add.2.body': '试试：“续约通话 friday @陈思雨 #维途 !high”。你一边输入，日期、负责人、客户和优先级就一边被识别出来。',
  'demo.tour.quick-add.3.title': '一次添加多个',
  'demo.tour.quick-add.3.body': '粘贴一份列表——比如会议记录——每一行都会成为一个单独的任务。',
  'demo.tour.board.title': '用看板安排团队的工作',
  'demo.tour.board.blurb': '每个团队一块看板，筛选和视图，任务的所有细节都在一个面板里。',
  'demo.tour.board.1.title': '看板承载团队的工作',
  'demo.tour.board.1.body': '打开客户成功看板。',
  'demo.tour.board.2.title': '把你的流程变成列',
  'demo.tour.board.2.body': '列是你要走过的步骤，卡片是有负责人、客户和日期的任务。工作推进时，把卡片拖到下一列。',
  'demo.tour.board.3.title': '筛选、保存、切换',
  'demo.tour.board.3.body': '只看我的或看所有人的，按人员、客户或日期筛选，保存的视图，用列表代替看板——还有归档。',
  'demo.tour.board.4.title': '打开一个任务',
  'demo.tour.board.4.body': '点击任意一张卡片。',
  'demo.tour.board.5.title': '任务的一切',
  'demo.tour.board.5.body': '关注它，把它关联到它在等待的任务，记录时间，勾选清单——最下面是它经历过的每一次变更。',
  'demo.tour.playbook.title': '一键开始客户入门',
  'demo.tour.playbook.blurb': '行动手册把团队的做事方式变成有负责人和日期的任务。',
  'demo.tour.playbook.1.title': '选一个客户',
  'demo.tour.playbook.1.body': '打开一个。',
  'demo.tour.playbook.2.title': '应用行动手册',
  'demo.tour.playbook.2.body': '行动手册是团队每次都会做的一组任务——用于入门、业务回顾、商机成交等。打开列表。',
  'demo.tour.playbook.3.title': '任务、负责人和日期一次到位',
  'demo.tour.playbook.3.body': '选一个，每个任务都会落到正确的看板上，有人负责，截止日期从今天算起。',
  'demo.tour.playbook.4.title': '编写你自己的',
  'demo.tour.playbook.4.body': '从示例开始或从零开始；当某件事发生时，自动化也可以替你应用行动手册。',
  'demo.tour.reviews.title': '与每个客户保持节奏',
  'demo.tour.reviews.blurb': '按时到来的业务回顾，所有会议都在一个日历上。',
  'demo.tour.reviews.1.title': '谁该做回顾了',
  'demo.tour.reviews.1.body': '业务回顾已逾期、30 天内到期或更晚的客户。标记一次完成，下次日期会自动顺延。',
  'demo.tour.reviews.2.title': '会议、通话和回顾',
  'demo.tour.reviews.2.body': '与客户的所有往来都汇集在一个日历上——按日、周、月或年查看。',
  'demo.tour.reviews.3.title': '你的，或团队的',
  'demo.tour.reviews.3.body': '负责人可以查看整个团队或某个人的日历——仅限其角色允许的范围。',
  'demo.tour.reports.title': '一分钟搭建一张报表',
  'demo.tour.reports.blurb': '第一天就有的概览，人人都会用的报表搭建器，以及每个人的一周。',
  'demo.tour.reports.1.title': '还没开口就已备好',
  'demo.tour.reports.1.body': '每周新进和完成的工作、谁在负责什么、记录的时间——无需搭建任何东西。',
  'demo.tour.reports.2.title': '一步步搭建你的报表',
  'demo.tour.reports.2.body': '选择要看的对象——任务、客户、商机——再筛选、分组，并选择统计方式。',
  'demo.tour.reports.3.title': '边搭建边看结果',
  'demo.tour.reports.3.body': '每次选择都会更新结果。保存后，可以放到仪表板或你的主页上。',
  'demo.tour.reports.4.title': '每个人的一周',
  'demo.tour.reports.4.body': '每个人的客户、未完成的工作和逾期事项——还有一个用于准备一对一面谈的视图。',
  'demo.tour.curaai.title': '问问 CuraAI',
  'demo.tour.curaai.blurb': '用你自己的话提问，答案附带出处。在这个演示中由 Claude 作答。',
  'demo.tour.curaai.1.title': '每个界面都有',
  'demo.tour.curaai.1.body': '打开 CuraAI。',
  'demo.tour.curaai.2.title': '从这样的问题开始',
