  'demo.tour.curaai.3.title': '或者用你自己的话问',
  'demo.tour.curaai.3.body': '“哪些客户本季度续约且有风险？”在这个演示中，Claude 根据文档和工作区作答，并说明每个答案的出处。',
  'demo.tour.curaai.4.title': '需要时有真人帮忙',
  'demo.tour.curaai.4.body': '如果答案不够，可以直接从这里联系支持团队——你的问题会一并带过去。',
  'demo.tour.portal.title': '每个客户一个门户',
  'demo.tour.portal.blurb': '客户在自己的门户中提交并跟进请求；你在看板上回复。',
  'demo.tour.portal.1.title': '现在你是客户',
  'demo.tour.portal.1.body': '吴佳琪在奎菲尔德零售工作，这是公司的客户之一。这里是奎菲尔德自己的门户，有自己的地址。',
  'demo.tour.portal.2.title': '只有属于他们的内容',
  'demo.tour.portal.2.body': '奎菲尔德与团队之间所有进行中的事项，以及每个请求的进展。其他客户的任何内容都绝不会出现。',
  'demo.tour.portal.3.title': '提需求很简单',
  'demo.tour.portal.3.body': '新请求会作为任务出现在团队的看板上；回复会回到这里，也会通过邮件送达。用上方的“当前身份”切回团队。',
